// SPDX-License-Identifier: Apache-2.0
// ck_tile seed for FlashInfer-Bench/025_rmsnorm_h4096.
//
// Exists to prove the ck_tile path end to end: a submission that assembles a
// ck_tile kernel out of the shipped pipeline/epilogue templates, compiles
// against the CK header tree the packager puts on the include path, and
// passes the AMD-derived tolerance. It is a path test; the tile shape below
// is the obvious one for hidden=4096 and was not tuned.
//
// ck_tile is header-only and ships no host launcher for rmsnorm2d -- upstream
// keeps that in an example directory that ROCm does not install -- so the
// launch is written out here: Problem -> Pipeline -> Kernel, then
// make_kernel/launch_kernel on the harness's stream.
#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <c10/hip/HIPStream.h>

#include "ck_tile/core.hpp"
#include "ck_tile/host/kernel_launch.hpp"
#include "ck_tile/host/stream_config.hpp"
#include "ck_tile/ops/common/generic_2d_block_shape.hpp"
#include "ck_tile/ops/epilogue/default_2d_epilogue.hpp"
#include "ck_tile/ops/rmsnorm2d.hpp"

namespace {

constexpr int kHidden = 4096;

// One row per block; 256 threads each hold 2 x 8 contiguous bf16 elements,
// which covers 4096 in a single pass -- hence the one-pass pipeline and
// kTwoPass = false.
using BlockShape = ck_tile::Generic2dBlockShape<ck_tile::sequence<1, kHidden>,
                                                ck_tile::sequence<1, 256>,
                                                ck_tile::sequence<1, 8>>;

using XDataType = ck_tile::bf16_t;
using ComputeDataType = float;  // fp32 accumulation, as the reference does

using Traits = ck_tile::Rmsnorm2dFwdTraits<
    false,  // kPadN -- 4096 is an exact multiple of the tile
    false,  // kSaveInvRms -- this problem does not want it
    false,  // kSaveUnquant
    false,  // kTwoPass
    ck_tile::Rmsnorm2dFusedAddEnum::NO_ADD,
    ck_tile::Rmsnorm2dFusedQuantEnum::NO_SWEEP,
    ck_tile::Rmsnorm2dSensitiveEnum::NO_SPECIFIC_MODEL>;

using Problem = ck_tile::Rmsnorm2dFwdPipelineProblem<
    XDataType,             // X
    XDataType,             // Gamma
    ComputeDataType,       // Compute
    XDataType,             // Y
    ck_tile::null_type,    // InvRms (not saved)
    ck_tile::null_type,    // UnquantY
    ck_tile::null_type,    // SmoothScale
    ck_tile::null_type,    // YScale
    BlockShape,
    Traits>;

using Pipeline = ck_tile::Rmsnorm2dFwdPipelineOnePass<Problem>;
using Epilogue = ck_tile::Default2DEpilogue<
    ck_tile::Default2DEpilogueProblem<ComputeDataType, XDataType, false, false>>;
using Kernel = ck_tile::Rmsnorm2dFwd<Pipeline, Epilogue>;

}  // namespace

torch::Tensor run(const torch::Tensor& hidden_states,
                  const torch::Tensor& weight) {
  TORCH_CHECK(hidden_states.dim() == 2, "hidden_states must be 2D");
  TORCH_CHECK(hidden_states.size(1) == kHidden, "hidden_size must be 4096");
  TORCH_CHECK(hidden_states.scalar_type() == torch::kBFloat16, "bf16 only");
  TORCH_CHECK(weight.scalar_type() == torch::kBFloat16, "bf16 only");

  auto x = hidden_states.contiguous();
  auto w = weight.contiguous();
  auto y = torch::empty_like(x);
  const int rows = static_cast<int>(x.size(0));

  ck_tile::Rmsnorm2dFwdHostArgs hargs{};
  hargs.p_x = x.data_ptr();
  hargs.p_x_residual = nullptr;
  hargs.p_sm_scale = nullptr;
  hargs.p_gamma = w.data_ptr();
  hargs.p_y = y.data_ptr();
  hargs.p_y_residual = nullptr;
  hargs.p_y_scale = nullptr;
  hargs.p_invRms = nullptr;
  hargs.p_y_unquant = nullptr;
  hargs.epsilon = 1e-5f;
  hargs.m = rows;
  hargs.n = kHidden;
  hargs.x_stride = kHidden;
  hargs.xr_stride = kHidden;
  hargs.y_stride = kHidden;
  hargs.yr_stride = kHidden;

  // Kernel::BlockSize() is a host function -- it calls is_wave32(), a runtime
  // query -- so the block size is a runtime dim3 here, not a template
  // argument. make_kernel's leading template parameter is MinBlockPerCu.
  const dim3 grids = Kernel::GridSize(hargs);
  const dim3 blocks = dim3(Kernel::BlockSize());
  // The one-pass pipeline reduces across warps through LDS. Passing 0 here
  // compiles and launches; it just reads and writes memory the block does not
  // own.
  const std::size_t lds_bytes = Kernel::GetSmemSize();

  // stream_config default-constructs with time_kernel_ = false: the harness
  // owns the timing bracket, and ck_tile's own timer would synchronize and
  // launch extra iterations inside it.
  ck_tile::stream_config s{};
  s.stream_id_ = c10::hip::getCurrentHIPStream();

  ck_tile::launch_kernel(
      s, ck_tile::make_kernel<1>(Kernel{}, grids, blocks, lds_bytes,
                                 Kernel::MakeKargs(hargs)));
  return y;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
  m.def("run", &run, "RMSNorm h4096 bf16 via ck_tile (ck_tile seed)");
}
